CREATE TABLE user_source_subscriptions (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES user_accounts(id) ON DELETE CASCADE, source_id text NOT NULL REFERENCES sources(id) ON DELETE RESTRICT, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, interval_minutes integer NOT NULL DEFAULT 60 CHECK (interval_minutes BETWEEN 1 AND 1440), reuse_window_minutes integer NOT NULL DEFAULT 10 CHECK (reuse_window_minutes BETWEEN 1 AND 1440), activated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id, source_id));
